    }
    int encodedLon = GeoEncodingUtils.encodeLongitude(latLonPointLon);
    int encodedLat = GeoEncodingUtils.encodeLatitude(latLonPointLat);
    latLonDecodedTriangles = new ArrayList<>(1);
    DecodedTriangle decoded = new DecodedTriangle();
    decoded.type = DecodedTriangle.TYPE.POINT;
    decoded.setValues(
