  static List<DecodedTriangle> decodeLatLonIndexableFields(Field[] indexableFields) {
    ShapeField coordinator = new ShapeField();
    coordinator.latLonFields = indexableFields;
    return coordinator.decodedFromCurrentLatLonIndexableFields();
