  static SpatialQuery.SpatialVisitor createXYSpatialVisitor(Component2D component2D) {
    ShapeField matcher = new ShapeField();
    matcher.xyMatchComponent = component2D;
    matcher.xyMatchTriangle = new DecodedTriangle();
    return matcher.buildXYSpatialVisitor();
  }

  private SpatialQuery.SpatialVisitor buildXYSpatialVisitor() {
    return new SpatialQuery.SpatialVisitor() {
      @Override
      protected Relation relate(byte[] minTriangle, byte[] maxTriangle) {
        decodeXYRange(minTriangle, maxTriangle);
        return relateDecodedXYRange();
      }

      @Override
      protected Predicate<byte[]> intersects() {
        return triangle -> {
          decodeXYMatchTriangle(triangle);
          return xyMatchIntersects();
