      }

      @Override
      protected Predicate<byte[]> within() {
        return triangle -> {
          decodeXYMatchTriangle(triangle);
          return xyMatchWithin();
        };
      }

      @Override
      protected Function<byte[], Component2D.WithinRelation> contains() {
        return triangle -> {
          decodeXYMatchTriangle(triangle);
          return xyMatchContains();
        };
