  private void decodeXYRange(byte[] minTriangle, byte[] maxTriangle) {
    if (xyMatchComponent == null && xyMatchTriangle == null) {
      xyMatchTriangle = new DecodedTriangle();
    }
    xyRangeMinY = XYEncodingUtils.decode(NumericUtils.sortableBytesToInt(minTriangle, 0));
    xyRangeMinX = XYEncodingUtils.decode(NumericUtils.sortableBytesToInt(minTriangle, BYTES));
    xyRangeMaxY = XYEncodingUtils.decode(NumericUtils.sortableBytesToInt(maxTriangle, 2 * BYTES));
    xyRangeMaxX = XYEncodingUtils.decode(NumericUtils.sortableBytesToInt(maxTriangle, 3 * BYTES));
  }

  private Relation relateDecodedXYRange() {
    return xyMatchComponent.relate(xyRangeMinX, xyRangeMaxX, xyRangeMinY, xyRangeMaxY);
