    xyMatchAX = XYEncodingUtils.decode(xyMatchTriangle.aX);
    xyMatchBY = XYEncodingUtils.decode(xyMatchTriangle.bY);
    xyMatchBX = XYEncodingUtils.decode(xyMatchTriangle.bX);
    xyMatchCY = XYEncodingUtils.decode(xyMatchTriangle.cY);
    xyMatchCX = XYEncodingUtils.decode(xyMatchTriangle.cX);
  }

  private boolean xyMatchIntersects() {
    Objects.requireNonNull(xyMatchComponent);
    if (xyMatchTriangle.type == DecodedTriangle.TYPE.POINT) {
